INSERT INTO public.news (id, title, text, published_at, payload) VALUES ('514cd7721cf86b6c1002', 'Спрос на сталь в России в 2026 году может снизиться на 0,5% год к году', 'Внутренний спрос на сталь в России в 2026 году может снизиться на 0,5% год к году, сообщила «Северсталь» в отчетности за третий квартал. Таким образом, объем потребления металла в этом году может составить около 38,7 млн тонн против 38,9 млн тонн годом ранее. Это соответствует уровню 2016 года, но ниже, чем в 2017–2024 годах. Ранее компания ожидала снижения потребления металла в 2026 году на 7%. Гендиректор «Северстали» Александр Шевелев отметил, что прогноз улучшен с учетом частичной реализации отложенного спроса в третьем квартале. Но, добавил топ-менеджер, рынку пока не удается восстановить утраченные объемы после снижения потребления в 2025 году на 14%. В четвертом квартале, прокомментировал господин Шевелев, ожидается сезонное охлаждение спроса и рынок остается ниже уровней, предшествовавших спаду. За девять месяцев 2026 года спрос на сталь вырос примерно на 1% год к году, оценивает «Северсталь». Подробнее читайте в материале «Потребители потянулись к металлу» .', '2026-10-20 13:55:38+00', '{"id": "514cd7721cf86b6c1002", "url": "https://www.kommersant.ru/doc/9043090", "text": "Внутренний спрос на сталь в России в 2026 году может снизиться на 0,5% год к году, сообщила «Северсталь» в отчетности за третий квартал. Таким образом, объем потребления металла в этом году может составить около 38,7 млн тонн против 38,9 млн тонн годом ранее. Это соответствует уровню 2016 года, но ниже, чем в 2017–2024 годах. Ранее компания ожидала снижения потребления металла в 2026 году на 7%. Гендиректор «Северстали» Александр Шевелев отметил, что прогноз улучшен с учетом частичной реализации отложенного спроса в третьем квартале. Но, добавил топ-менеджер, рынку пока не удается восстановить утраченные объемы после снижения потребления в 2025 году на 14%. В четвертом квартале, прокомментировал господин Шевелев, ожидается сезонное охлаждение спроса и рынок остается ниже уровней, предшествовавших спаду. За девять месяцев 2026 года спрос на сталь вырос примерно на 1% год к году, оценивает «Северсталь». Подробнее читайте в материале «Потребители потянулись к металлу» .", "title": "Спрос на сталь в России в 2026 году может снизиться на 0,5% год к году", "topics": ["metallurgy"], "regions": [], "countries": [], "published_at": "2026-10-20T13:55:38+00:00"}') ON CONFLICT DO NOTHING;
INSERT INTO public.news (id, title, text, published_at, payload) VALUES ('90b13aa4900dc3e623c9', 'Доля Ozon в продажах крупных селлеров на маркетплейсах выросла почти до 60%', 'С января по август текущего года доля Ozon в продажах крупных селлеров на маркетплейсах выросла почти до 60%, следует из данных MPStats Data. Так, в январе 57,54% продаж в сегменте приходилось на Wildberries, 42,46% — на Ozon. В августе же доля Wildberries сократилась до 41,71%, а у Ozon выросла до 58,29%. В исследование вошли крупнейшие в своих товарных категориях продавцы: аналитики отобрали по 200 селлеров с самой высокой выручкой на Wildberries и Ozon в каждой из десяти категорий за январь—август 2026 года. Среди категорий — дом и мебель, одежда и обувь, продукты, электроника и бытовая техника и другие. Итоговая база составила 2,97 тыс. бизнесов. Данные подтверждают в рекламном агентстве Mafia Agency. У небольших продавцов из нижней четверти выборки около 59% продаж приходится на Ozon и 41% — на Wildberries, говорят в компании. У продавцов из средних групп Ozon также лидирует — его доля составляет примерно 55–59%, добавляют в Mafia Agency. В компании изменения в позициях маркетплейсов связывают с летними сбоями в их логистике. Подробнее читайте в материале «Здоровая коммерция» .', '2026-10-20 14:19:45+00', '{"id": "90b13aa4900dc3e623c9", "url": "https://www.kommersant.ru/doc/9043106", "text": "С января по август текущего года доля Ozon в продажах крупных селлеров на маркетплейсах выросла почти до 60%, следует из данных MPStats Data. Так, в январе 57,54% продаж в сегменте приходилось на Wildberries, 42,46% — на Ozon. В августе же доля Wildberries сократилась до 41,71%, а у Ozon выросла до 58,29%. В исследование вошли крупнейшие в своих товарных категориях продавцы: аналитики отобрали по 200 селлеров с самой высокой выручкой на Wildberries и Ozon в каждой из десяти категорий за январь—август 2026 года. Среди категорий — дом и мебель, одежда и обувь, продукты, электроника и бытовая техника и другие. Итоговая база составила 2,97 тыс. бизнесов. Данные подтверждают в рекламном агентстве Mafia Agency. У небольших продавцов из нижней четверти выборки около 59% продаж приходится на Ozon и 41% — на Wildberries, говорят в компании. У продавцов из средних групп Ozon также лидирует — его доля составляет примерно 55–59%, добавляют в Mafia Agency. В компании изменения в позициях маркетплейсов связывают с летними сбоями в их логистике. Подробнее читайте в материале «Здоровая коммерция» .", "title": "Доля Ozon в продажах крупных селлеров на маркетплейсах выросла почти до 60%", "topics": ["retail_ecommerce"], "regions": [], "countries": [], "published_at": "2026-10-20T14:19:45+00:00"}') ON CONFLICT DO NOTHING;
INSERT INTO public.news (id, title, text, published_at, payload) VALUES ('69c2aad5f1dd168aead7', 'Цена на природный газ в Европе превысила 90 евро впервые за четыре года', 'Цена на природный газ в Европе впервые с декабря 2022 г. превысила 90 евро. По данным агентства Bloomberg, стоимость ресурса повышает угрозу возобновления энергетического кризиса в преддверии зимнего отопительного сезона.

Стоимость ноябрьского фьючерса на хабе TTF в Нидерландах выросла на 2,5% и на пике достигла 90,24 евро за МВт/ч. По состоянию на 16:43 мск котировки немного снизились – до 89,73 евро за МВт/ч. Разница с ценой закрытия составляет 1,91%.

Агентство пишет, что Европе придется переплачивать, чтобы привлечь достаточное количество энергоресурса этой зимой. Спрос на сжиженный природный газ (СПГ) со стороны Азии создает предпосылки для более ожесточенных торгов с наступлением холодов. Хранилища газа в регионе сейчас заполнены примерно на 75%, что является самым низким показателем за сезон за всю историю наблюдений начиная с 2009 г. Ситуация еще более остра в Германии, где уровень заполнения составляет чуть более 61%.

Трейдеры остаются в состоянии повышенной готовности. Экспорт газа из Персидского залива, на долю которого в 2025 г. приходилось около пятой части мирового объема СПГ, по-прежнему нарушен конфликтом на Ближнем Востоке. Цены на СПГ в Азии также подскочили до максимума с 2022 г.

9 октября Politico писало , что Европа может столкнуться с дефицитом газа зимой и ростом коммунальных платежей. При этом запасы газа в ЕС находятся на минимальном за последние 15 лет уровне для этого времени года. Одна из причин возможного энергетического кризиса – нарушение глобальных поставок энергоносителей из-за конфликта на Ближнем Востоке.', '2026-10-20 14:02:24+00', '{"id": "69c2aad5f1dd168aead7", "url": "https://www.vedomosti.ru/business/news/2026/10/20/1238594-tsena-na-gaz", "text": "Цена на природный газ в Европе впервые с декабря 2022 г. превысила 90 евро. По данным агентства Bloomberg, стоимость ресурса повышает угрозу возобновления энергетического кризиса в преддверии зимнего отопительного сезона.\n\nСтоимость ноябрьского фьючерса на хабе TTF в Нидерландах выросла на 2,5% и на пике достигла 90,24 евро за МВт/ч. По состоянию на 16:43 мск котировки немного снизились – до 89,73 евро за МВт/ч. Разница с ценой закрытия составляет 1,91%.\n\nАгентство пишет, что Европе придется переплачивать, чтобы привлечь достаточное количество энергоресурса этой зимой. Спрос на сжиженный природный газ (СПГ) со стороны Азии создает предпосылки для более ожесточенных торгов с наступлением холодов. Хранилища газа в регионе сейчас заполнены примерно на 75%, что является самым низким показателем за сезон за всю историю наблюдений начиная с 2009 г. Ситуация еще более остра в Германии, где уровень заполнения составляет чуть более 61%.\n\nТрейдеры остаются в состоянии повышенной готовности. Экспорт газа из Персидского залива, на долю которого в 2025 г. приходилось около пятой части мирового объема СПГ, по-прежнему нарушен конфликтом на Ближнем Востоке. Цены на СПГ в Азии также подскочили до максимума с 2022 г.\n\n9 октября Politico писало , что Европа может столкнуться с дефицитом газа зимой и ростом коммунальных платежей. При этом запасы газа в ЕС находятся на минимальном за последние 15 лет уровне для этого времени года. Одна из причин возможного энергетического кризиса – нарушение глобальных поставок энергоносителей из-за конфликта на Ближнем Востоке.", "title": "Цена на природный газ в Европе превысила 90 евро впервые за четыре года", "topics": ["energy"], "regions": [], "countries": [], "published_at": "2026-10-20T14:02:24+00:00"}') ON CONFLICT DO NOTHING;
INSERT INTO public.news (id, title, text, published_at, payload) VALUES ('10d56ab3f602a1602152', 'НАУФОР утвердила стандарт ответственного инвестирования для управляющих ПИФов', 'Совет директоров НАУФОР утвердил стандарт ответственного инвестирования для управляющих компаний паевых инвестиционных фондов. Документ распространяется на УК открытых и биржевых фондов с акциями российских эмитентов. Требования действуют при доле голосов УК по акциям эмитента во всех фондах свыше 0,5% — независимо от формы участия в собрании акционеров. УК сможет выдвигать кандидата в совет директоров эмитента, если совокупная доля ее голосующих акций превышает 2%, а политика голосования допускает такое выдвижение. Воздержаться от голосования разрешено в исключительных случаях, когда нельзя обоснованно определить вариант, отвечающий интересам пайщиков; мотивы должны быть задокументированы. Документ также перечисляет обстоятельства, при которых УК вправе не участвовать в собрании: запреты закона или суда, обременение акций, технические сбои, конфликт интересов и риски для пайщиков. НАУФОР разработала стандарт с учетом рекомендаций Банка России, указывавшего на пассивность институциональных инвесторов в корпоративном управлении.', '2026-10-20 14:27:45+00', '{"id": "10d56ab3f602a1602152", "url": "https://www.kommersant.ru/doc/9043110", "text": "Совет директоров НАУФОР утвердил стандарт ответственного инвестирования для управляющих компаний паевых инвестиционных фондов. Документ распространяется на УК открытых и биржевых фондов с акциями российских эмитентов. Требования действуют при доле голосов УК по акциям эмитента во всех фондах свыше 0,5% — независимо от формы участия в собрании акционеров. УК сможет выдвигать кандидата в совет директоров эмитента, если совокупная доля ее голосующих акций превышает 2%, а политика голосования допускает такое выдвижение. Воздержаться от голосования разрешено в исключительных случаях, когда нельзя обоснованно определить вариант, отвечающий интересам пайщиков; мотивы должны быть задокументированы. Документ также перечисляет обстоятельства, при которых УК вправе не участвовать в собрании: запреты закона или суда, обременение акций, технические сбои, конфликт интересов и риски для пайщиков. НАУФОР разработала стандарт с учетом рекомендаций Банка России, указывавшего на пассивность институциональных инвесторов в корпоративном управлении.", "title": "НАУФОР утвердила стандарт ответственного инвестирования для управляющих ПИФов", "topics": ["financial_markets", "regulation"], "regions": [], "countries": [], "published_at": "2026-10-20T14:27:45+00:00"}') ON CONFLICT DO NOTHING;
INSERT INTO public.news (id, title, text, published_at, payload) VALUES ('514cd7721cf86b6c100257ca571cfa9be8fbab704f723ba6d6cfe27eefbc831d', 'Спрос на сталь в России в 2026 году может снизиться на 0,5% год к году', 'Внутренний спрос на сталь в России в 2026 году может снизиться на 0,5% год к году, сообщила «Северсталь» в отчетности за третий квартал. Таким образом, объем потребления металла в этом году может составить около 38,7 млн тонн против 38,9 млн тонн годом ранее. Это соответствует уровню 2016 года, но ниже, чем в 2017–2024 годах. Ранее компания ожидала снижения потребления металла в 2026 году на 7%. Гендиректор «Северстали» Александр Шевелев отметил, что прогноз улучшен с учетом частичной реализации отложенного спроса в третьем квартале. Но, добавил топ-менеджер, рынку пока не удается восстановить утраченные объемы после снижения потребления в 2025 году на 14%. В четвертом квартале, прокомментировал господин Шевелев, ожидается сезонное охлаждение спроса и рынок остается ниже уровней, предшествовавших спаду. За девять месяцев 2026 года спрос на сталь вырос примерно на 1% год к году, оценивает «Северсталь». Подробнее читайте в материале «Потребители потянулись к металлу» .', '2026-10-20 13:55:38+00', '{"id": "514cd7721cf86b6c100257ca571cfa9be8fbab704f723ba6d6cfe27eefbc831d", "url": "https://www.kommersant.ru/doc/9043090", "text": "Внутренний спрос на сталь в России в 2026 году может снизиться на 0,5% год к году, сообщила «Северсталь» в отчетности за третий квартал. Таким образом, объем потребления металла в этом году может составить около 38,7 млн тонн против 38,9 млн тонн годом ранее. Это соответствует уровню 2016 года, но ниже, чем в 2017–2024 годах. Ранее компания ожидала снижения потребления металла в 2026 году на 7%. Гендиректор «Северстали» Александр Шевелев отметил, что прогноз улучшен с учетом частичной реализации отложенного спроса в третьем квартале. Но, добавил топ-менеджер, рынку пока не удается восстановить утраченные объемы после снижения потребления в 2025 году на 14%. В четвертом квартале, прокомментировал господин Шевелев, ожидается сезонное охлаждение спроса и рынок остается ниже уровней, предшествовавших спаду. За девять месяцев 2026 года спрос на сталь вырос примерно на 1% год к году, оценивает «Северсталь». Подробнее читайте в материале «Потребители потянулись к металлу» .", "title": "Спрос на сталь в России в 2026 году может снизиться на 0,5% год к году", "topics": ["metallurgy"], "regions": [], "countries": [], "published_at": "2026-10-20T13:55:38+00:00"}') ON CONFLICT DO NOTHING;
INSERT INTO public.news (id, title, text, published_at, payload) VALUES ('90b13aa4900dc3e623c9c472a8858134f5f60cfc4a8258235ecb8a6c71d4a376', 'Доля Ozon в продажах крупных селлеров на маркетплейсах выросла почти до 60%', 'С января по август текущего года доля Ozon в продажах крупных селлеров на маркетплейсах выросла почти до 60%, следует из данных MPStats Data. Так, в январе 57,54% продаж в сегменте приходилось на Wildberries, 42,46% — на Ozon. В августе же доля Wildberries сократилась до 41,71%, а у Ozon выросла до 58,29%. В исследование вошли крупнейшие в своих товарных категориях продавцы: аналитики отобрали по 200 селлеров с самой высокой выручкой на Wildberries и Ozon в каждой из десяти категорий за январь—август 2026 года. Среди категорий — дом и мебель, одежда и обувь, продукты, электроника и бытовая техника и другие. Итоговая база составила 2,97 тыс. бизнесов. Данные подтверждают в рекламном агентстве Mafia Agency. У небольших продавцов из нижней четверти выборки около 59% продаж приходится на Ozon и 41% — на Wildberries, говорят в компании. У продавцов из средних групп Ozon также лидирует — его доля составляет примерно 55–59%, добавляют в Mafia Agency. В компании изменения в позициях маркетплейсов связывают с летними сбоями в их логистике. Подробнее читайте в материале «Здоровая коммерция» .', '2026-10-20 14:19:45+00', '{"id": "90b13aa4900dc3e623c9c472a8858134f5f60cfc4a8258235ecb8a6c71d4a376", "url": "https://www.kommersant.ru/doc/9043106", "text": "С января по август текущего года доля Ozon в продажах крупных селлеров на маркетплейсах выросла почти до 60%, следует из данных MPStats Data. Так, в январе 57,54% продаж в сегменте приходилось на Wildberries, 42,46% — на Ozon. В августе же доля Wildberries сократилась до 41,71%, а у Ozon выросла до 58,29%. В исследование вошли крупнейшие в своих товарных категориях продавцы: аналитики отобрали по 200 селлеров с самой высокой выручкой на Wildberries и Ozon в каждой из десяти категорий за январь—август 2026 года. Среди категорий — дом и мебель, одежда и обувь, продукты, электроника и бытовая техника и другие. Итоговая база составила 2,97 тыс. бизнесов. Данные подтверждают в рекламном агентстве Mafia Agency. У небольших продавцов из нижней четверти выборки около 59% продаж приходится на Ozon и 41% — на Wildberries, говорят в компании. У продавцов из средних групп Ozon также лидирует — его доля составляет примерно 55–59%, добавляют в Mafia Agency. В компании изменения в позициях маркетплейсов связывают с летними сбоями в их логистике. Подробнее читайте в материале «Здоровая коммерция» .", "title": "Доля Ozon в продажах крупных селлеров на маркетплейсах выросла почти до 60%", "topics": ["retail_ecommerce"], "regions": [], "countries": [], "published_at": "2026-10-20T14:19:45+00:00"}') ON CONFLICT DO NOTHING;
INSERT INTO public.news (id, title, text, published_at, payload) VALUES ('69c2aad5f1dd168aead7a88eef022eab3b91e52d0a43177c575acb17299facd3', 'Цена на природный газ в Европе превысила 90 евро впервые за четыре года', 'Цена на природный газ в Европе впервые с декабря 2022 г. превысила 90 евро. По данным агентства Bloomberg, стоимость ресурса повышает угрозу возобновления энергетического кризиса в преддверии зимнего отопительного сезона.

Стоимость ноябрьского фьючерса на хабе TTF в Нидерландах выросла на 2,5% и на пике достигла 90,24 евро за МВт/ч. По состоянию на 16:43 мск котировки немного снизились – до 89,73 евро за МВт/ч. Разница с ценой закрытия составляет 1,91%.

Агентство пишет, что Европе придется переплачивать, чтобы привлечь достаточное количество энергоресурса этой зимой. Спрос на сжиженный природный газ (СПГ) со стороны Азии создает предпосылки для более ожесточенных торгов с наступлением холодов. Хранилища газа в регионе сейчас заполнены примерно на 75%, что является самым низким показателем за сезон за всю историю наблюдений начиная с 2009 г. Ситуация еще более остра в Германии, где уровень заполнения составляет чуть более 61%.

Трейдеры остаются в состоянии повышенной готовности. Экспорт газа из Персидского залива, на долю которого в 2025 г. приходилось около пятой части мирового объема СПГ, по-прежнему нарушен конфликтом на Ближнем Востоке. Цены на СПГ в Азии также подскочили до максимума с 2022 г.

9 октября Politico писало , что Европа может столкнуться с дефицитом газа зимой и ростом коммунальных платежей. При этом запасы газа в ЕС находятся на минимальном за последние 15 лет уровне для этого времени года. Одна из причин возможного энергетического кризиса – нарушение глобальных поставок энергоносителей из-за конфликта на Ближнем Востоке.', '2026-10-20 14:02:24+00', '{"id": "69c2aad5f1dd168aead7a88eef022eab3b91e52d0a43177c575acb17299facd3", "url": "https://www.vedomosti.ru/business/news/2026/10/20/1238594-tsena-na-gaz", "text": "Цена на природный газ в Европе впервые с декабря 2022 г. превысила 90 евро. По данным агентства Bloomberg, стоимость ресурса повышает угрозу возобновления энергетического кризиса в преддверии зимнего отопительного сезона.\n\nСтоимость ноябрьского фьючерса на хабе TTF в Нидерландах выросла на 2,5% и на пике достигла 90,24 евро за МВт/ч. По состоянию на 16:43 мск котировки немного снизились – до 89,73 евро за МВт/ч. Разница с ценой закрытия составляет 1,91%.\n\nАгентство пишет, что Европе придется переплачивать, чтобы привлечь достаточное количество энергоресурса этой зимой. Спрос на сжиженный природный газ (СПГ) со стороны Азии создает предпосылки для более ожесточенных торгов с наступлением холодов. Хранилища газа в регионе сейчас заполнены примерно на 75%, что является самым низким показателем за сезон за всю историю наблюдений начиная с 2009 г. Ситуация еще более остра в Германии, где уровень заполнения составляет чуть более 61%.\n\nТрейдеры остаются в состоянии повышенной готовности. Экспорт газа из Персидского залива, на долю которого в 2025 г. приходилось около пятой части мирового объема СПГ, по-прежнему нарушен конфликтом на Ближнем Востоке. Цены на СПГ в Азии также подскочили до максимума с 2022 г.\n\n9 октября Politico писало , что Европа может столкнуться с дефицитом газа зимой и ростом коммунальных платежей. При этом запасы газа в ЕС находятся на минимальном за последние 15 лет уровне для этого времени года. Одна из причин возможного энергетического кризиса – нарушение глобальных поставок энергоносителей из-за конфликта на Ближнем Востоке.", "title": "Цена на природный газ в Европе превысила 90 евро впервые за четыре года", "topics": ["energy"], "regions": [], "countries": [], "published_at": "2026-10-20T14:02:24+00:00"}') ON CONFLICT DO NOTHING;
INSERT INTO public.news (id, title, text, published_at, payload) VALUES ('10d56ab3f602a1602152ffe1889fb933bc134223462086a8a34411dc9c56fae4', 'НАУФОР утвердила стандарт ответственного инвестирования для управляющих ПИФов', 'Совет директоров НАУФОР утвердил стандарт ответственного инвестирования для управляющих компаний паевых инвестиционных фондов. Документ распространяется на УК открытых и биржевых фондов с акциями российских эмитентов. Требования действуют при доле голосов УК по акциям эмитента во всех фондах свыше 0,5% — независимо от формы участия в собрании акционеров. УК сможет выдвигать кандидата в совет директоров эмитента, если совокупная доля ее голосующих акций превышает 2%, а политика голосования допускает такое выдвижение. Воздержаться от голосования разрешено в исключительных случаях, когда нельзя обоснованно определить вариант, отвечающий интересам пайщиков; мотивы должны быть задокументированы. Документ также перечисляет обстоятельства, при которых УК вправе не участвовать в собрании: запреты закона или суда, обременение акций, технические сбои, конфликт интересов и риски для пайщиков. НАУФОР разработала стандарт с учетом рекомендаций Банка России, указывавшего на пассивность институциональных инвесторов в корпоративном управлении.', '2026-10-20 14:27:45+00', '{"id": "10d56ab3f602a1602152ffe1889fb933bc134223462086a8a34411dc9c56fae4", "url": "https://www.kommersant.ru/doc/9043110", "text": "Совет директоров НАУФОР утвердил стандарт ответственного инвестирования для управляющих компаний паевых инвестиционных фондов. Документ распространяется на УК открытых и биржевых фондов с акциями российских эмитентов. Требования действуют при доле голосов УК по акциям эмитента во всех фондах свыше 0,5% — независимо от формы участия в собрании акционеров. УК сможет выдвигать кандидата в совет директоров эмитента, если совокупная доля ее голосующих акций превышает 2%, а политика голосования допускает такое выдвижение. Воздержаться от голосования разрешено в исключительных случаях, когда нельзя обоснованно определить вариант, отвечающий интересам пайщиков; мотивы должны быть задокументированы. Документ также перечисляет обстоятельства, при которых УК вправе не участвовать в собрании: запреты закона или суда, обременение акций, технические сбои, конфликт интересов и риски для пайщиков. НАУФОР разработала стандарт с учетом рекомендаций Банка России, указывавшего на пассивность институциональных инвесторов в корпоративном управлении.", "title": "НАУФОР утвердила стандарт ответственного инвестирования для управляющих ПИФов", "topics": ["financial_markets", "regulation"], "regions": [], "countries": [], "published_at": "2026-10-20T14:27:45+00:00"}') ON CONFLICT DO NOTHING;


